changeSet.sql:
DO $functions$
DECLARE
    definition text;
BEGIN
    SELECT pg_get_functiondef('enforce_practice_current_revision_projection()'::regprocedure)
      INTO definition;
    definition := replace(
        definition,
        'ON area.id = practice.practice_group_id',
        'ON practice_group.id = practice.practice_group_id');
    EXECUTE definition;
END
$functions$;

rollback.sql:
DO $functions$
DECLARE
    definition text;
BEGIN
    SELECT pg_get_functiondef('enforce_practice_current_revision_projection()'::regprocedure)
      INTO definition;
    definition := replace(
        definition,
        'ON practice_group.id = practice.practice_group_id',
        'ON area.id = practice.practice_group_id');
    EXECUTE definition;
END
$functions$;
